#!/bin/zsh
# L7 step 2's profile (one pair, a flight recording per side; jfr_agg.py reads the two JSONs): the eager corpus compile run OUTSIDE Bazel (its action is cached by inputs), from the
# execution root, alternating main's core sources and the change's, six pairs; the median typeAll decides.
set -u
EXEC="$(bazel info execution_root)"
WIP="$1"
mkdir -p "$EXEC/bazel-out/darwin_arm64-fastbuild/bin/spec/eager_corpus_compile_tmp"
mkdir -p runs/homework/l7/eager_jfr
for i in 1; do
  for side in main change; do
    if [ "$side" = main ]; then git checkout -q origin/main -- core/src/main; else git checkout -q "$WIP" -- core/src/main; fi
    bazel build --remote_download_all //spec:eager_corpus_compile > /dev/null 2>&1 || { echo "build failed ($side $i)"; exit 1; }
    OUT="$PWD/runs/homework/l7/eager_jfr/${side}"; rm -rf "$OUT"; mkdir -p "$OUT/tmp"
    ( cd "$EXEC" && external/rules_java++toolchains+remotejdk25_macos_aarch64/bin/java -Duser.timezone=GMT -Duser.language=en -Duser.country=US -Dfile.encoding=UTF-8 -Djava.io.tmpdir=$OUT/tmp -Xmx4096m -XX:StartFlightRecording:filename=$OUT/rec.jfr,settings=profile,jdk.ExecutionSample#period=1ms -Duser.timezone=GMT -Dlegend.engine.root=external/+http_archive+legend_engine_src/pom.xml -Dlegend.pure.root=external/+http_archive+legend_pure_src/pom.xml -cp bazel-out/darwin_arm64-fastbuild/bin/spec/libspec_tests_lib.jar:bazel-out/darwin_arm64-fastbuild/bin/spec/libclaims.jar:bazel-out/darwin_arm64-fastbuild/bin/spec/libsource_tree.jar:bazel-out/darwin_arm64-fastbuild/bin/base/libbase.jar:bazel-out/darwin_arm64-fastbuild/bin/json/libjson.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libspi.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libcache.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libvalues.jar:bazel-out/darwin_arm64-fastbuild/bin/core/liberror.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libdiagnostics.jar:bazel-out/darwin_arm64-fastbuild/bin/core/liblexer.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libsql.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libprotocol.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libmodel.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libparser.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libbuiltin.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libplatform.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libcompiler_element_type.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libsql_dialect.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libdatabase.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libexecution_plan.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libcompiler.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libnormalizer.jar:bazel-out/darwin_arm64-fastbuild/bin/core/liblineage.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libvalidation.jar:bazel-out/darwin_arm64-fastbuild/bin/core/liblowering.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libplan.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libresolver.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libsetup.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libexec.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libprobe.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libtestdatagen.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libplanner.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libpure_v1.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libdriver.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libide.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libtest.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libserver_lib.jar:bazel-out/darwin_arm64-fastbuild/bin/spec/libgenerators.jar:bazel-out/darwin_arm64-fastbuild/bin/spec/libimports_generator.jar:bazel-out/darwin_arm64-fastbuild/bin/testing/libtesting.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_java+/java/runfiles/src/main/java/com/google/devtools/build/runfiles/librunfiles.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_java+/java/runfiles/src/main/java/com/google/devtools/build/runfiles/libauto_bazel_repository.jar:bazel-out/darwin_arm64-fastbuild/bin/tools/junit/libjunit.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-engine/1.11.3/junit-platform-engine-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/apiguardian/apiguardian-api/1.1.2/apiguardian-api-1.1.2.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-commons/1.11.3/junit-platform-commons-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/opentest4j/opentest4j/1.3.0/opentest4j-1.3.0.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-launcher/1.11.3/junit-platform-launcher-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-reporting/1.11.3/junit-platform-reporting-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/jupiter/junit-jupiter-engine/5.11.3/junit-jupiter-engine-5.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/jupiter/junit-jupiter-api/5.11.3/junit-jupiter-api-5.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-suite-engine/1.11.3/junit-platform-suite-engine-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-suite-api/1.11.3/junit-platform-suite-api-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/platform/junit-platform-suite-commons/1.11.3/junit-platform-suite-commons-1.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/vintage/junit-vintage-engine/5.11.3/junit-vintage-engine-5.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/com/tngtech/archunit/archunit/1.3.0/archunit-1.3.0.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/slf4j/slf4j-api/2.0.12/slf4j-api-2.0.12.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/com/tngtech/archunit/archunit-junit5/1.3.0/archunit-junit5-1.3.0.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/com/tngtech/archunit/archunit-junit5-api/1.3.0/archunit-junit5-api-1.3.0.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/com/tngtech/archunit/archunit-junit5-engine/1.3.0/archunit-junit5-engine-1.3.0.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/com/tngtech/archunit/archunit-junit5-engine-api/1.3.0/archunit-junit5-engine-api-1.3.0.jar:external/+product_jars+duckdb_jdbc/jar/duckdb_jdbc-1.4.4.0.jar:bazel-out/darwin_arm64-fastbuild/bin/external/rules_jvm_external++maven+maven_test/org/junit/jupiter/junit-jupiter-params/5.11.3/junit-jupiter-params-5.11.3.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libduckdb_load.jar:external/+product_jars+h2/jar/h2-2.1.214.jar:external/+product_jars+postgresql/jar/postgresql-42.7.13.jar:external/+product_jars+sqlite_jdbc/jar/sqlite-jdbc-3.47.1.0.jar:bazel-out/darwin_arm64-fastbuild/bin/core/libshadow_binding.jar com.legend.rcorpus.EagerCorpusCompileProbe "$OUT" ) > "$OUT/stdout.log" 2>&1
    echo "$side $i $(grep -oE 'build=[0-9]+ms typeAll=[0-9]+ms' "$OUT/eager-corpus.txt" 2>/dev/null || echo FAILED)"
  done
done
git checkout -q "$WIP" -- core/src/main
for side in main change; do ( cd "$EXEC" && external/rules_java++toolchains+remotejdk25_macos_aarch64/bin/jfr print --json --stack-depth 200 --events jdk.ExecutionSample "$OLDPWD/runs/homework/l7/eager_jfr/$side/rec.jfr" > "$OLDPWD/runs/homework/l7/eager_jfr/$side/rec.json" ); done
